import java.util.*;
import java.io.*;

public class DStress2_Variant4 {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int length = scanner.nextInt();
        String s = scanner.next();
        System.out.println(new DStress2_Variant4().calculateMinimumCost(s.toCharArray()));
        scanner.close();
    }

    int INF = Integer.MAX_VALUE / 3;

    int calculateMinimumCost(char[] sequence) {
        List<Integer> vIndices = new ArrayList<>();
        List<Integer> kIndices = new ArrayList<>();
        List<Integer> otherIndices = new ArrayList<>();
        for (int i = 0; i < sequence.length; i++) {
            switch (sequence[i]) {
                case 'V': vIndices.add(i); break;
                case 'K': kIndices.add(i); break;
                default: otherIndices.add(i); break;
            }
        }
        int[][][][] dp = new int[2][vIndices.size() + 1][kIndices.size() + 1][otherIndices.size() + 1];
        for (int[][][] layer : dp)
            for (int[][] row : layer)
                for (int[] col : row)
                    Arrays.fill(col, INF);
        dp[0][0][0][0] = 0;
        for (int vCount = 0; vCount <= vIndices.size(); vCount++) {
            for (int kCount = 0; kCount <= kIndices.size(); kCount++) {
                for (int oCount = 0; oCount <= otherIndices.size(); oCount++) {
                    for (int lastFlag = 0; lastFlag < 2; lastFlag++) {
                        int costSoFar = dp[lastFlag][vCount][kCount][oCount];
                        if (costSoFar == INF) continue;
                        if (vCount < vIndices.size()) {
                            int newCost = costSoFar + count(vIndices.get(vCount), kCount, kIndices) + count(vIndices.get(vCount), oCount, otherIndices);
                            dp[1][vCount + 1][kCount][oCount] = Math.min(dp[1][vCount + 1][kCount][oCount], newCost);
                        }
                        if (kCount < kIndices.size() && lastFlag == 0) {
                            int newCost = costSoFar + count(kIndices.get(kCount), vCount, vIndices) + count(kIndices.get(kCount), oCount, otherIndices);
                            dp[0][vCount][kCount + 1][oCount] = Math.min(dp[0][vCount][kCount + 1][oCount], newCost);
                        }
                        if (oCount < otherIndices.size()) {
                            int newCost = costSoFar + count(otherIndices.get(oCount), vCount, vIndices) + count(otherIndices.get(oCount), kCount, kIndices);
                            dp[0][vCount][kCount][oCount + 1] = Math.min(dp[0][vCount][kCount][oCount + 1], newCost);
                        }
                    }
                }
            }
        }
        return Math.min(dp[0][vIndices.size()][kIndices.size()][otherIndices.size()], dp[1][vIndices.size()][kIndices.size()][otherIndices.size()]);
    }

    private int count(int position, int startIdx, List<Integer> list) {
        int cnt = 0;
        for (int i = startIdx; i < list.size(); i++) {
            if (list.get(i) < position) cnt++;
        }
        return cnt;
    }
}
