def calculate_minimum_cost(sequence):
    INF = float('inf') / 3
    v_indices = []
    k_indices = []
    other_indices = []

    for i, ch in enumerate(sequence):
        if ch == 'V':
            v_indices.append(i)
        elif ch == 'K':
            k_indices.append(i)
        else:
            other_indices.append(i)

    v_size = len(v_indices)
    k_size = len(k_indices)
    o_size = len(other_indices)

    # Initialize 4D DP array
    dp = [[[[INF for _ in range(o_size + 1)] for _ in range(k_size + 1)] for _ in range(v_size + 1)] for _ in range(2)]
    dp[0][0][0][0] = 0

    def count(pos, start_idx, lst):
        cnt = 0
        for i in range(start_idx, len(lst)):
            if lst[i] < pos:
                cnt += 1
        return cnt

    for v_count in range(v_size + 1):
        for k_count in range(k_size + 1):
            for o_count in range(o_size + 1):
                for last_flag in range(2):
                    cost_so_far = dp[last_flag][v_count][k_count][o_count]
                    if cost_so_far == INF:
                        continue
                    # Add V
                    if v_count < v_size:
                        new_cost = cost_so_far + count(v_indices[v_count], k_count, k_indices) + count(v_indices[v_count], o_count, other_indices)
                        if new_cost < dp[1][v_count + 1][k_count][o_count]:
                            dp[1][v_count + 1][k_count][o_count] = new_cost
                    # Add K
                    if k_count < k_size and last_flag == 0:
                        new_cost = cost_so_far + count(k_indices[k_count], v_count, v_indices) + count(k_indices[k_count], o_count, other_indices)
                        if new_cost < dp[0][v_count][k_count + 1][o_count]:
                            dp[0][v_count][k_count + 1][o_count] = new_cost
                    # Add other
                    if o_count < o_size:
                        new_cost = cost_so_far + count(other_indices[o_count], v_count, v_indices) + count(other_indices[o_count], k_count, k_indices)
                        if new_cost < dp[0][v_count][k_count][o_count + 1]:
                            dp[0][v_count][k_count][o_count + 1] = new_cost

    return int(min(dp[0][v_size][k_size][o_size], dp[1][v_size][k_size][o_size]))

